/*
 * openwave_main.c -- OpenWave application entry point.
 *
 * M1 milestone: project skeleton.  Prints the application version to
 * the console and exits cleanly.  Signal acquisition, DSP, UI and
 * storage are added in subsequent milestones.
 */

#include <stdio.h>

#define OPENWAVE_NAME    "OpenWave"
#define OPENWAVE_VERSION "0.1.0"

int main(int argc, char *argv[])
{
  printf("%s v%s\n", OPENWAVE_NAME, OPENWAVE_VERSION);
  printf("High-precision data acquisition & real-time waveform/parameter display\n");
  printf("Platform: STM32H7A3 (NUCLEO-H7A3ZI-Q) / openvela (NuttX)\n");

  return 0;
}

