      int pos;
      if (v > hyst) pos = 1;
      else if (v < -hyst) pos = -1;
      else continue;  /* dead zone */

      if (prev_pos != 0 && pos != prev_pos)
        {
          crossings += 1.0;
        }
      prev_pos = pos;
    }

  /* each full cycle has 2 zero crossings */
  return crossings * sample_rate / (2.0 * (n - 1));
}
```

