              temp_re = wr * re[j] - wi * im[j];
              temp_im = wr * im[j] + wi * re[j];
              re[j] = re[k] - temp_re;
              im[j] = im[k] - temp_im;
              re[k] += temp_re;
              im[k] += temp_im;
