```c
int wave_dsp_fft_freq(const int32_t *data, int n, double sample_rate,
                      double *re, double *im, double *freq_hz, double *mag_peak)
{
  int i, peak = -1;
  double maxmag = 0.0;
  /* copy data into re, zero im, subtract mean for AC coupling */
  double mean = wave_dsp_mean(data, n);
  for (i = 0; i < n; i++) { re[i] = data[i] - mean; im[i] = 0.0; }
  wave_dsp_fft(re, im, n);
  /* find peak bin 1..n/2-1 (skip DC) */
  for (i = 1; i < n/2; i++)
    {
      double mag = sqrt(re[i]*re[i] + im[i]*im[i]);
      if (mag > maxmag) { maxmag = mag; peak = i; }
    }
  if (peak <= 0) return -1;
  *freq_hz = (double)peak * sample_rate / n;
  *mag_peak = maxmag;
  return 0;
}
```

