+double wave_dsp_mean(const int32_t *data, int n)
+{
+  double sum = 0.0;
+  int i;
+
+  if (data == NULL || n <= 0)
+    {
+      return 0.0;
+    }
+
+  for (i = 0; i < n; i++)
+    {
+      sum += data[i];
+    }
+
+  return sum / n;
