+{
+  double sum = 0.0;
+  double v;
+  int i;
+
+  if (data == NULL || n <= 0)
+    {
+      return 0.0;
+    }
+
+  for (i = 0; i < n; i++)
+    {
+      v = (double)data[i];
+      sum += v * v;
+    }
+
+  return sqrt(sum / n);
