+{
+  int32_t vmin = data != NULL && n > 0 ? data[0] : 0;
+  int i;
+
+  for (i = 1; i < n; i++)
+    {
+      if (data[i] < vmin)
+        {
+          vmin = data[i];
+        }
+    }
+
+  return vmin;
+}
