#include <math.h>
#include <stdio.h>
#include <stdint.h>
#include "wave_dsp.h"

#define RATE 50000.0
#define N 256

static void gen_square(int32_t *buf, int n, double vlow, double vhigh, double duty, double freq, double rate)
{
  int i;
  for (i = 0; i < n; i++)
    {
      double t = i / rate;
      double cycle = fmod(t * freq, 1.0);
      buf[i] = (cycle < duty) ? (int32_t)vhigh : (int32_t)vlow;
    }
}

static void gen_sine(int32_t *buf, int n, double offset, double amp, double freq, double rate)
{
  int i;
  for (i = 0; i < n; i++)
    {
      buf[i] = (int32_t)(offset + amp * sin(2.0 * M_PI * freq * i / rate));
    }
}

int main(void)
{
  int32_t buf[N];
  struct wave_stats_s st;
  double re[N], im[N], ff;
  int ret;

  /* 1) DC 1.65 V (raw 32767) */
  for (int i = 0; i < N; i++) buf[i] = 32767;
  wave_dsp_analyze(buf, N, RATE, &st);
  printf("DC:     mean=%.1f rms=%.1f vpp=%.1f f=%.1f\n", st.mean_raw, st.rms_raw, st.vpp_raw, st.freq_zc);
  ret = wave_dsp_fft_freq(buf, N, RATE, re, im, &ff, NULL);
  printf("DC FFT: ret=%d\n", ret);

  /* 2) Square 0..65535, 50%, 1 kHz */
  gen_square(buf, N, 0, 65535, 0.5, 1000.0, RATE);
  wave_dsp_analyze(buf, N, RATE, &st);
  printf("SQ:     mean=%.1f rms=%.1f vpp=%.1f f=%.1f\n", st.mean_raw, st.rms_raw, st.vpp_raw, st.freq_zc);
  wave_dsp_fft_freq(buf, N, RATE, re, im, &ff, NULL);
  printf("SQ FFT: %.1f\n", ff);

  /* 3) Sine 1.65V offset, 1.5V amp, 1 kHz */
  gen_sine(buf, N, 32767, 29789, 1000.0, RATE);  /* amp 1.5V = 0.4545*65535 = 29789 */
  wave_dsp_analyze(buf, N, RATE, &st);
  printf("SIN:    mean=%.1f rms=%.1f vpp=%.1f f=%.1f\n", st.mean_raw, st.rms_raw, st.vpp_raw, st.freq_zc);
  wave_dsp_fft_freq(buf, N, RATE, re, im, &ff, NULL);
  printf("SIN FFT: %.1f\n", ff);

  return 0;
}
