/*
 * openwave_main.c -- OpenWave application entry point.
 *
 * M4 milestone: adds per-channel statistics (mean / RMS / Vpp /
 * zero-crossing frequency / FFT) over a sampling window.  The raw
 * printing mode from M2/M3 remains available with -w 0.
