int wave_ui_init(struct wave_ui_s *ui)
{
  struct fb_videoinfo_s vinfo;

  if (ui == NULL)
    {
      return -EINVAL;
    }

  memset(ui, 0, sizeof(*ui));
  ui->fd = -1;

  ui->fd = open(WAVE_UI_DEVPATH, O_RDWR);
  if (ui->fd < 0)
    {
      return -errno;
    }

  if (ioctl(ui->fd, LCDDEVIO_GETVIDEOINFO,
            (unsigned long)(uintptr_t)&vinfo) < 0)
    {
      close(ui->fd);
      ui->fd = -1;
      return -errno;
    }

  ui->xres = vinfo.xres;
  ui->yres = vinfo.yres;
  ui->opened = true;

  /* Turn the display on and clear it. */
  ioctl(ui->fd, LCDDEVIO_SETPOWER, 1);
  wave_ui_clear(ui);
  wave_ui_flush(ui);
  return 0;
}

void wave_ui_deinit(struct wave_ui_s *ui)
{
  if (ui != NULL && ui->opened)
    {
      ioctl(ui->fd, LCDDEVIO_SETPOWER, 0);
      close(ui->fd);
      ui->fd = -1;
      ui->opened = false;
    }
}

void wave_ui_clear(struct wave_ui_s *ui)
{
  if (ui != NULL)
    {
      memset(ui->fb, 0, sizeof(ui->fb));
    }
}

void wave_ui_pixel(struct wave_ui_s *ui, int x, int y, bool on)
{
  uint8_t mask;
  int byte;
  int bit;

  if (ui == NULL || x < 0 || x >= WAVE_UI_WIDTH ||
      y < 0 || y >= WAVE_UI_HEIGHT)
    {
      return;
    }

  byte = y * WAVE_UI_STRIDE + (x >> 3);
  bit = 7 - (x & 7); /* MSB-first: bit 7 is the leftmost pixel */
  mask = (uint8_t)(1u << bit);

  if (on)
    {
      ui->fb[byte] |= mask;
    }
  else
    {
      ui->fb[byte] &= (uint8_t)~mask;
    }
}

void wave_ui_line(struct wave_ui_s *ui, int x0, int y0, int x1, int y1,
                  bool on)
{
  int dx;
  int dy;
  int sx;
  int sy;
  int err;
  int e2;

  dx = x1 > x0 ? x1 - x0 : x0 - x1;
  dy = y1 > y0 ? y1 - y0 : y0 - y1;
  sx = x0 < x1 ? 1 : -1;
  sy = y0 < y1 ? 1 : -1;
  err = dx - dy;

  for (; ; )
    {
      wave_ui_pixel(ui, x0, y0, on);
      if (x0 == x1 && y0 == y1)
        {
          break;
        }

      e2 = 2 * err;
      if (e2 > -dy)
        {
          err -= dy;
          x0 += sx;
        }

      if (e2 < dx)
        {
          err += dx;
          y0 += sy;
        }
    }
}

void wave_ui_text(struct wave_ui_s *ui, int x, int y, const char *s)
{
  int col;
  int row;

  if (ui == NULL || s == NULL)
    {
      return;
    }

  for (; *s != '\0' && x < WAVE_UI_WIDTH; s++)
    {
      char c = *s;
      int idx;

      if (c >= 'a' && c <= 'z')
        {
          c = (char)(c - 'a' + 'A');
        }

      idx = c - 0x20;
      if (idx < 0 || idx > 63)
        {
          x += 6; /* unsupported character: advance */
          continue;
        }

      for (col = 0; col < 5 && x + col < WAVE_UI_WIDTH; col++)
        {
          uint8_t colbits = g_wave_font[idx][col];

          for (row = 0; row < 7; row++)
            {
              if ((colbits & (1u << row)) != 0)
                {
                  wave_ui_pixel(ui, x + col, y + row, true);
                }
            }
        }

      x += 6;
    }
}

void wave_ui_waveform(struct wave_ui_s *ui, const int32_t *data, int n,
                      int x0, int x1, int y0, int y1)
{
  int32_t vmin;
  int32_t vmax;
  int span;
  int px;
  int prev_y = -1;

  if (ui == NULL || data == NULL || n <= 0 || x1 <= x0 || y1 <= y0)
    {
      return;
    }

  vmin = data[0];
  vmax = data[0];
  for (px = 1; px < n; px++)
    {
      if (data[px] < vmin)
        {
          vmin = data[px];
        }

      if (data[px] > vmax)
        {
          vmax = data[px];
        }
    }

  span = (int)(vmax - vmin);
  if (span < 1)
    {
      span = 1;
    }

  for (px = x0; px <= x1; px++)
    {
      int si = (px - x0) * (n - 1) / (x1 - x0);
      int32_t v = data[si];
      int y;

      y = y1 - (int)((int64_t)(v - vmin) * (y1 - y0) / span);
      if (y < y0)
        {
          y = y0;
        }
      else if (y > y1)
        {
          y = y1;
        }

      if (prev_y >= y0)
        {
          wave_ui_line(ui, px - 1, prev_y, px, y, true);
        }
      else
        {
          wave_ui_pixel(ui, px, y, true);
        }

      prev_y = y;
    }
}

int wave_ui_flush(struct wave_ui_s *ui)
{
  struct lcddev_area_s area;

  if (ui == NULL || !ui->opened)
    {
      return -EINVAL;
    }

  area.row_start = 0;
  area.row_end = WAVE_UI_HEIGHT - 1;
  area.col_start = 0;
  area.col_end = WAVE_UI_WIDTH - 1;
  area.stride = WAVE_UI_STRIDE;
  area.data = ui->fb;

  if (ioctl(ui->fd, LCDDEVIO_PUTAREA,
            (unsigned long)(uintptr_t)&area) < 0)
    {
      return -errno;
    }

  return 0;
}

/*
 * wave_ui.h -- OpenWave SSD1306 OLED drawing (via /dev/lcd0).
 *
 * M5 milestone: draws the captured waveform and measured parameters on
 * the 128x64 monochrome OLED through the NuttX LCD character driver.
 */

#ifndef __APPS_OPENWAVE_WAVE_UI_H
#define __APPS_OPENWAVE_WAVE_UI_H

#include <nuttx/config.h>

#include <stdbool.h>
#include <stdint.h>

/* Display geometry (SSD1306 128x64). */
#define WAVE_UI_WIDTH   128
#define WAVE_UI_HEIGHT  64
#define WAVE_UI_STRIDE  (WAVE_UI_WIDTH / 8)
#define WAVE_UI_FBSIZE  (WAVE_UI_STRIDE * WAVE_UI_HEIGHT)

#define WAVE_UI_DEVPATH "/dev/lcd0"

struct wave_ui_s
{
  int  fd;       /* open file descriptor for /dev/lcd0 */
  bool opened;   /* true once the device is open */
  uint16_t xres; /* reported horizontal resolution */
  uint16_t yres; /* reported vertical resolution */

  /* 1-bpp shadow frame buffer (bit 7 = leftmost pixel of a byte). */
  uint8_t fb[WAVE_UI_FBSIZE];
};

/* Open /dev/lcd0, query the video info and power the display on.
 * Returns 0 on success or a negative errno value.
 */
int wave_ui_init(struct wave_ui_s *ui);

/* Power the display off and close it. */
void wave_ui_deinit(struct wave_ui_s *ui);

/* Clear the shadow frame buffer (does not touch the display). */
void wave_ui_clear(struct wave_ui_s *ui);

/* Set one pixel in the shadow frame buffer. */
void wave_ui_pixel(struct wave_ui_s *ui, int x, int y, bool on);

/* Draw a line (Bresenham) in the shadow frame buffer. */
void wave_ui_line(struct wave_ui_s *ui, int x0, int y0, int x1, int y1,
                  bool on);

/* Draw a null-terminated string with the built-in 5x7 font.  Lowercase
 * letters are drawn as uppercase.  Only ASCII 0x20..0x5F are supported.
 */
void wave_ui_text(struct wave_ui_s *ui, int x, int y, const char *s);

/* Plot n samples scaled into the rectangle [x0..x1] x [y0..y1]. */
void wave_ui_waveform(struct wave_ui_s *ui, const int32_t *data, int n,
                      int x0, int x1, int y0, int y1);

/* Push the whole shadow frame buffer to the display via LCDDEVIO_PUTAREA.
 * Returns 0 on success or a negative errno value.
 */
int wave_ui_flush(struct wave_ui_s *ui);

#endif /* __APPS_OPENWAVE_WAVE_UI_H */

