#ifndef GPIO_SSD1306_RST
#  define GPIO_SSD1306_RST (GPIO_OUTPUT | GPIO_PUSHPULL | GPIO_SPEED_50MHz | \
                            GPIO_PORTE | GPIO_PIN13)
#endif

static struct lcd_dev_s *g_lcddev;

int board_ssd1306_initialize(int busno)
{
  struct spi_dev_s *spi;
  const int devno = 0;

  /* Configure OLED control pins and pulse the hardware reset. */
  stm32_configgpio(GPIO_SPI3_CS0);
  stm32_configgpio(GPIO_SSD1306_DC);
  stm32_configgpio(GPIO_SSD1306_RST);
  stm32_gpiowrite(GPIO_SSD1306_RST, false);
  usleep(10000);
  stm32_gpiowrite(GPIO_SSD1306_RST, true);
  usleep(10000);

  spi = stm32_spibus_initialize(busno);
  if (spi == NULL)
    {
      lcderr("ERROR: Failed to initialize SPI port %d\n", busno);
      return -ENODEV;
    }

  g_lcddev = ssd1306_initialize(spi, NULL, devno);
  if (g_lcddev == NULL)
    {
      lcderr("ERROR: Failed to bind SPI port %d to OLED %d\n", busno, devno);
      return -ENODEV;
    }

  lcdinfo("Bound SPI port %d to OLED %d\n", busno, devno);
  g_lcddev->setpower(g_lcddev, CONFIG_LCD_MAXPOWER);
  ssd1306_fill(g_lcddev, 0x00);  /* start blank */
  return OK;
}

struct lcd_dev_s *board_ssd1306_getdev(void)
{
  return g_lcddev;
}

int board_lcd_initialize(void)
{
  int ret;

  ret = board_ssd1306_initialize(3);  /* SPI3 */
  if (ret < 0)
    {
      lcderr("ERROR: Failed to initialize SSD1306\n");
      return ret;
    }

  return OK;
}

struct lcd_dev_s *board_lcd_getdev(int devno)
{
  return board_ssd1306_getdev();
}

void board_lcd_uninitialize(void)
{
}

#endif /* CONFIG_LCD_SSD1306_SPI */
