                      int x0, int x1, int y0, int y1)
{
  int32_t vmin;
  int32_t vmax;
  int span;
  int px;
  int prev_y = -1;

  if (ui == NULL || data == NULL || n <= 0 || x1 <= x0 || y1 <= y0)
    {
      return;
    }

  vmin = data[0];
  vmax = data[0];
  for (px = 1; px < n; px++)
    {
      if (data[px] < vmin)
        {
          vmin = data[px];
        }

      if (data[px] > vmax)
        {
          vmax = data[px];
        }
    }

  span = (int)(vmax - vmin);
  if (span < 1)
    {
      span = 1;
    }

  for (px = x0; px <= x1; px++)
    {
      int si = (px - x0) * (n - 1) / (x1 - x0);
      int32_t v = data[si];
      int y;

      y = y1 - (int)((int64_t)(v - vmin) * (y1 - y0) / span);
      if (y < y0)
        {
