/*
 * wave_ui.c -- OpenWave SSD1306 OLED drawing implementation.
 *
 * Draws into a 1-KB shadow frame buffer and flushes it to the display
 * through the /dev/lcd0 character driver (LCDDEVIO_PUTAREA).
