/*
 * openwave_main.c -- OpenWave application entry point.
 *
 * M5 milestone: draws the waveform and measured parameters on the
 * SSD1306 OLED (/dev/lcd0) when available.  Serial output remains.
 */

#include <nuttx/config.h>

#include <inttypes.h>
#include <limits.h>
