```c
#include <nuttx/config.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <nuttx/input/buttons.h>
#include "wave_input.h"

#ifndef CONFIG_OPENWAVE_BUTTON_DEVPATH
#  define CONFIG_OPENWAVE_BUTTON_DEVPATH "/dev/buttons"
#endif

#define WAVE_INPUT_LONG_MS  500

int wave_input_init(struct wave_input_s *in)
{
  if (in == NULL) return -EINVAL;
  memset(in, 0, sizeof(*in));
  in->fd = -1;
  in->fd = open(CONFIG_OPENWAVE_BUTTON_DEVPATH, O_RDONLY);
  if (in->fd < 0) return -errno;
  ioctl(in->fd, BTNIOC_SUPPORTED, (unsigned long)(uintptr_t)&in->supported);
  if (in->supported == 0) in->supported = 1; /* fallback: at least button 0 */
  in->opened = true;
  return 0;
}

/* poll for a button event without blocking; returns:
 *  1  event produced (*event/*button set)
 *  0  no event
 *  <0 negative errno on error
 */
int wave_input_poll(struct wave_input_s *in,
                    enum wave_input_event_e *event, int *button)
{
  struct pollfd fds;
  btn_buttonset_t cur = 0;
  uint32_t bit;
  ssize_t n;
  int ret;
  struct timespec now;
  int64_t ms;

  if (in == NULL || !in->opened || event == NULL || button == NULL)
    return -EINVAL;

  fds.fd = in->fd;
  fds.events = POLLIN;
  fds.revents = 0;
  ret = poll(&fds, 1, 0);
  if (ret <= 0) return 0;  /* timeout or error (ret<0 → caller could check errno; keep 0) */

  n = read(in->fd, &cur, sizeof(cur));
  if (n != (ssize_t)sizeof(cur)) return 0;

  for (bit = 0; bit < 32; bit++)
    {
      if ((in->supported & (1u << bit)) == 0) continue;
      if ((cur & (1u << bit)) != 0 && (in->pressed & (1u << bit)) == 0)
        {
          /* rising edge */
          clock_gettime(WAVE_CLOCK_ID, &in->t0[bit]);
          in->pressed |= (1u << bit);
        }
      else if ((cur & (1u << bit)) == 0 && (in->pressed & (1u << bit)) != 0)
        {
          /* falling edge: compute duration */
          clock_gettime(WAVE_CLOCK_ID, &now);
          ms = (int64_t)(now.tv_sec - in->t0[bit].tv_sec) * 1000 +
               (now.tv_nsec - in->t0[bit].tv_nsec) / 1000000;
          in->pressed &= ~(1u << bit);
          *button = (int)bit;
          *event = (ms >= WAVE_INPUT_LONG_MS) ? WAVE_INPUT_LONG : WAVE_INPUT_SHORT;
          return 1;
        }
    }

  return 0;
}
```

