```c
int wave_store_save(struct wave_store_s *st, const struct wave_snapshot_s *snap)
{
  struct wave_snapshot_s check;
  struct mtd_erase_s erase;
  int ret;

  if (st == NULL || snap == NULL) return -EINVAL;

  /* Always print the snapshot (console record). */
  printf("[snapshot] #%u ch=%u %04d-%02d-%02d %02d:%02d:%02d "
         "mean=%.3fV rms=%.3fV vpp=%.3fV f=%.1fHz n=%u\n",
         snap->seq, snap->channel,
         snap->tm_year + 1900, snap->tm_mon + 1, snap->tm_mday,
         snap->tm_hour, snap->tm_min, snap->tm_sec,
         snap->mean_v, snap->rms_v, snap->vpp_v, snap->freq_hz,
         snap->nsamples);

  if (!st->opened || !st->geo_ok)
    {
      return -ENODEV;   /* console-only mode */
    }

  erase.startblock = st->neraseblocks - 1;
  erase.nblocks = 1;
  ret = ioctl(st->fd, MTDIOC_ERASESECTORS, (unsigned long)(uintptr_t)&erase);
  if (ret < 0) { printf("[store] erase failed: %d\n", -errno); return -errno; }

  ret = pwrite(st->fd, snap, sizeof(*snap), st->last_offset);
  if (ret != (ssize_t)sizeof(*snap))
    { printf("[store] write failed: %d\n", ret < 0 ? -errno : -EIO); return ret < 0 ? -errno : -EIO; }

  memset(&check, 0, sizeof(check));
  ret = pread(st->fd, &check, sizeof(check), st->last_offset);
  if (ret == (ssize_t)sizeof(check) && check.magic == WAVE_SNAPSHOT_MAGIC &&
      check.crc == wave_store_crc(...))
    printf("[store] OK (flash offset 0x%lx)\n", (unsigned long)st->last_offset);
  else
    printf("[store] verify failed\n");
  return 0;
}
