/****************************************************************************
 * wave_store.h -- OpenWave snapshot persistence (M6)
 *
 * Stores small snapshots (stats + RTC timestamp) into the last erase
 * block of the internal program flash (/dev/progmem0).  If the MTD
 * device is unavailable, snapshots are printed to the console only.
 ****************************************************************************/

#ifndef __OPENWAVE_WAVE_STORE_H
#define __OPENWAVE_WAVE_STORE_H

#include <stdbool.h>
#include <stdint.h>
#include <sys/types.h>

#define WAVE_SNAPSHOT_MAGIC  0x4f57534eu  /* "OWSN" */

struct wave_snapshot_s
{
  uint32_t magic;      /* WAVE_SNAPSHOT_MAGIC (filled by wave_store_save) */
  uint32_t seq;        /* snapshot sequence number */
  uint8_t  channel;    /* ADC channel */
  uint8_t  reserved[3];
  int      tm_year;    /* years since 1900 */
  int      tm_mon;     /* month, 0-11 */
  int      tm_mday;    /* day of month, 1-31 */
  int      tm_hour;    /* hour, 0-23 */
  int      tm_min;     /* minute, 0-59 */
  int      tm_sec;     /* second, 0-59 */
  float    mean_v;     /* mean voltage (V) */
  float    rms_v;      /* RMS voltage (V) */
  float    vpp_v;      /* peak-to-peak voltage (V) */
  float    freq_hz;    /* zero-crossing frequency (Hz) */
  uint32_t nsamples;   /* samples used */
  uint32_t crc;        /* checksum (filled by wave_store_save) */
};

struct wave_store_s
{
  int      fd;             /* /dev/progmem0 descriptor */
  bool     opened;
  bool     geo_ok;         /* geometry known and safe to use */
  uint32_t erasesize;      /* erase block size (bytes) */
  uint32_t neraseblocks;   /* number of erase blocks */
  off_t    last_offset;    /* byte offset of the last erase block */
  uint32_t seq;            /* next snapshot sequence number */
};

int  wave_store_init(struct wave_store_s *st);
void wave_store_deinit(struct wave_store_s *st);

/* Save one snapshot: print it to the console and, when flash storage is
 * available, erase the last erase block and write the snapshot there.
 * Returns 0 on success, negative errno on failure, -ENODEV when running
 * in console-only mode (storage unavailable).  On success st->seq is
 * incremented by the caller. */
int  wave_store_save(struct wave_store_s *st,
                     const struct wave_snapshot_s *snap);
#endif
```

wave_store.c:

```c
/****************************************************************************
 * wave_store.c -- OpenWave snapshot persistence (M6)
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#include <nuttx/mtd/mtd.h>

#include "wave_store.h"

#ifndef CONFIG_OPENWAVE_STORE_DEVPATH
#  define CONFIG_OPENWAVE_STORE_DEVPATH "/dev/progmem0"
#endif

/* Safety: never erase below this offset.  The firmware image lives at
 * the start of flash; snapshots are stored in the very last block. */
#define WAVE_STORE_MIN_SAFE_OFFSET (1024u * 1024u)

static uint32_t wave_store_crc(const void *data, size_t len)
{
  const uint8_t *p = (const uint8_t *)data;
  uint32_t crc = 0x811c9dc5u;
  size_t i;

  for (i = 0; i < len; i++)
    {
      crc ^= p[i];
      crc *= 0x01000193u;
    }

  return crc;
}

int wave_store_init(struct wave_store_s *st)
{
  struct mtd_geometry_s geo;

  if (st == NULL)
    {
      return -EINVAL;
    }

  memset(st, 0, sizeof(*st));
  st->fd = -1;

  st->fd = open(CONFIG_OPENWAVE_STORE_DEVPATH, O_RDWR);
  if (st->fd < 0)
    {
      return -errno;
    }

  st->opened = true;

  if (ioctl(st->fd, MTDIOC_GEOMETRY,
            (unsigned long)(uintptr_t)&geo) == 0 &&
      geo.erasesize > 0 && geo.neraseblocks > 0)
    {
      st->erasesize = geo.erasesize;
      st->neraseblocks = geo.neraseblocks;
      st->last_offset = (off_t)(geo.neraseblocks - 1) * geo.erasesize;

      /* Only use the tail of the flash, far away from the firmware. */
      st->geo_ok = (st->last_offset >= WAVE_STORE_MIN_SAFE_OFFSET);
    }

  return 0;
}

void wave_store_deinit(struct wave_store_s *st)
{
  if (st != NULL && st->opened)
    {
      close(st->fd);
      st->fd = -1;
      st->opened = false;
    }
}

int wave_store_save(struct wave_store_s *st,
                    const struct wave_snapshot_s *snap)
{
  struct wave_snapshot_s out;
  struct wave_snapshot_s check;
  struct mtd_erase_s erase;
  ssize_t nbytes;
  int ret;

  if (st == NULL || snap == NULL)
    {
      return -EINVAL;
    }

  /* Console record: always available. */
  printf("[snapshot] #%u ch=%u %04d-%02d-%02d %02d:%02d:%02d "
         "mean=%.3fV rms=%.3fV vpp=%.3fV f=%.1fHz n=%u\n",
         snap->seq, snap->channel,
         snap->tm_year + 1900, snap->tm_mon + 1, snap->tm_mday,
         snap->tm_hour, snap->tm_min, snap->tm_sec,
         snap->mean_v, snap->rms_v, snap->vpp_v, snap->freq_hz,
         snap->nsamples);

  if (!st->opened || !st->geo_ok)
    {
      printf("[store] console-only mode (flash unavailable)\n");
      return -ENODEV;
    }

  /* Fill in magic and checksum. */
  out = *snap;
  out.magic = WAVE_SNAPSHOT_MAGIC;
  out.crc = 0;
  out.crc = wave_store_crc(&out, sizeof(out));

  /* Erase only the last erase block. */
  erase.startblock = st->neraseblocks - 1;
  erase.nblocks = 1;
  ret = ioctl(st->fd, MTDIOC_ERASESECTORS,
              (unsigned long)(uintptr_t)&erase);
  if (ret < 0)
    {
      printf("[store] erase failed: %d\n", -errno);
      return -errno;
    }

  nbytes = pwrite(st->fd, &out, sizeof(out), st->last_offset);
  if (nbytes != (ssize_t)sizeof(out))
    {
      printf("[store] write failed: %d\n", nbytes < 0 ? -errno : -EIO);
      return nbytes < 0 ? -errno : -EIO;
    }

  /* Read it back and verify. */
  memset(&check, 0, sizeof(check));
  nbytes = pread(st->fd, &check, sizeof(check), st->last_offset);
  if (nbytes == (ssize_t)sizeof(check) &&
      check.magic == WAVE_SNAPSHOT_MAGIC &&
      check.crc == wave_store_crc(&check, sizeof(check)))
    {
      printf("[store] OK: flash offset 0x%lx, %u bytes\n",
             (unsigned long)st->last_offset, (unsigned)sizeof(check));
      return 0;
    }

  printf("[store] verify failed\n");
  return -EIO;
}
```

