 * Returns:
 *   1  an event is ready: *event and *button are set
 *   0  no event yet (or input not opened)
 *  <0  negative errno on failure
 */

int wave_input_poll(struct wave_input_s *in,
                    enum wave_input_event_e *event, int *button);

