      else if (strcmp(argv[argi], "-D") == 0 && argi + 1 < argc)
        {
          pwm_duty = strtol(argv[++argi], NULL, 10);
          if (pwm_duty < 0)
            {
              pwm_duty = 0;
            }
          else if (pwm_duty > 100)
            {
              pwm_duty = 100;
            }
        }
      else if (strcmp(argv[argi], "-w") == 0 && argi + 1 < argc)
        {
          window = strtol(argv[++argi], NULL, 10);
          if (window < 0)
            {
              window = 0;
            }
          else if (window > WAVE_DSP_MAX_FFT)
            {
              window = WAVE_DSP_MAX_FFT;
            }
        }
      else if (strcmp(argv[argi], "-c") == 0 && argi + 1 < argc)
        {
          channel = strtol(argv[++argi], NULL, 10);
          if (channel < 0 || channel > 255)
            {
              channel = CONFIG_OPENWAVE_ANALYZE_CHANNEL;
            }
        }
      else if (strcmp(argv[argi], "-h") == 0)
        {
          show_usage(argv[0]);
          return 0;
        }
      else
        {
          printf("Unknown option: %s\n", argv[argi]);
          show_usage(argv[0]);
          return 1;
        }
    }

  printf("%s v%s\n", OPENWAVE_NAME, OPENWAVE_VERSION);
  printf("M6: acquisition + DSP + OLED + PWM + buttons -- adc %s, "
         "%ld %s (%s)\n",
         adc_devpath, remaining,
         window > 0 ? "window(s)" : "samples",
         remaining == 0 ? "unlimited" : "then exit");

  /* Optional test-signal generator (PWM -> jumper -> ADC). */

  if (pwm_freq > 0)
    {
      ret = wave_gen_init(&gen, pwm_devpath);
      if (ret < 0)
        {
          printf("open %s failed: %d\n", pwm_devpath, -ret);
          return 2;
        }

      ret = wave_gen_start(&gen, (uint32_t)pwm_freq, (uint32_t)pwm_duty);
      if (ret < 0)
        {
          printf("PWM start failed: %d\n", -ret);
          wave_gen_deinit(&gen);
          return 2;
        }

      pwm_on = true;
      printf("PWM test signal: %s, %ld Hz, %ld %%\n",
             pwm_devpath, pwm_freq, pwm_duty);
    }

  ret = wave_core_init(&core, adc_devpath);
  if (ret < 0)
    {
      printf("open %s failed: %d\n", adc_devpath, -ret);
      if (pwm_on)
        {
          wave_gen_deinit(&gen);
        }

      return 2;
    }

  core.swtrig = swtrig;
  printf("ADC ready: %d configured channel(s)\n", core.nchannels);

  /* Try to bring up the OLED; not fatal if it is absent. */

  if (wave_ui_init(&ui) == 0)
    {
      ui_on = true;
      printf("OLED ready: %u x %u\n", ui.xres, ui.yres);
    }

  /* M6: buttons, LEDs, RTC and snapshot store (all optional). */

  if (wave_input_init(&input) < 0)
    {
      printf("input: /dev/buttons unavailable (button control disabled)\n");
    }
  else
    {
      printf("input: buttons ready\n");
    }

  if (wave_store_init(&store) < 0)
    {
      printf("store: flash unavailable (console-only snapshots)\n");
    }
  else
    {
      printf("store: flash ready (last block at offset 0x%lx, "
             "%u bytes)\n",
             (unsigned long)store.last_offset, (unsigned)store.erasesize);
    }

  led_fd = open(CONFIG_OPENWAVE_LED_DEVPATH, O_WRONLY);
  if (led_fd < 0)
    {
      printf("led: /dev/userleds unavailable (alarm LED disabled)\n");
    }

  rtc_fd = open(CONFIG_OPENWAVE_RTC_DEVPATH, O_RDONLY);
  if (rtc_fd < 0)
    {
      printf("rtc: /dev/rtc0 unavailable (snapshots without timestamp)\n");
    }

  /* Map the requested channel to the short-press cycle list. */

  for (i = 0; i < (int)ch_count; i++)
    {
      if (g_channels[i] == (uint8_t)channel)
        {
          ch_index = (uint32_t)i;
          break;
        }
    }

  infinite = (remaining == 0);
  if (window > 0)
    {
      printf("Analysis mode: channel %ld, %ld samples/window\n",
             channel, window);

      while (infinite || remaining > 0)
        {
          ret = wave_core_collect_channel(&core, (uint8_t)channel,
                                          win, (int)window, &rate);
          if (ret < 0)
            {
              printf("collect failed: %d\n", -ret);
              break;
            }

          ret = wave_core_analyze(win, (int)window, rate, &stats);
          if (ret < 0)
            {
              printf("analyze failed: %d\n", -ret);
              break;
            }

          printf("[stats] ch=%ld n=%u rate=%.0f Hz | "
                 "mean=%.3f V rms=%.3f V vpp=%.3f V f=%.1f Hz",
                 channel, stats.nsamples, rate,
                 wave_core_raw_to_volt(stats.mean_raw),
                 wave_core_raw_to_volt(stats.rms_raw),
                 wave_core_raw_to_volt(stats.vpp_raw),
                 stats.freq_zc);

          if (wave_dsp_fft_freq(win, (int)window, rate,
                                s_fft_re, s_fft_im, &ffreq, NULL) == 0)
            {
              printf(" | f_fft=%.1f Hz", ffreq);
            }

          printf("\n");
          fflush(stdout);

          if (ui_on)
            {
              wave_ui_clear(&ui);
              snprintf(line, sizeof(line), "CH=%ld RATE=%.0f HZ",
                       channel, rate);
              wave_ui_text(&ui, 0, 0, line);
              wave_ui_waveform(&ui, win, (int)window, 0, 127, 8, 55);
              snprintf(line, sizeof(line), "RMS=%.2f P=%.2f F=%.0f",
                       wave_core_raw_to_volt(stats.rms_raw),
                       wave_core_raw_to_volt(stats.vpp_raw),
                       stats.freq_zc);
              wave_ui_text(&ui, 0, 56, line);
              wave_ui_flush(&ui);
            }

          /* M6: handle button events (non-blocking). */

          if (input.opened)
            {
              enum wave_input_event_e ev;
              int btn;

              if (wave_input_poll(&input, &ev, &btn) == 1)
                {
                  if (ev == WAVE_INPUT_SHORT)
                    {
                      ch_index = (ch_index + 1) % ch_count;
                      channel = g_channels[ch_index];
                      printf("[input] short: channel -> %ld\n", channel);
                    }
                  else
                    {
                      struct wave_snapshot_s snap;

                      memset(&snap, 0, sizeof(snap));
                      wave_main_read_rtc(rtc_fd, &snap);
                      snap.seq = store.seq;
                      snap.channel = (uint8_t)channel;
                      snap.mean_v = (float)wave_core_raw_to_volt(
                                        stats.mean_raw);
                      snap.rms_v = (float)wave_core_raw_to_volt(
                                       stats.rms_raw);
                      snap.vpp_v = (float)wave_core_raw_to_volt(
                                       stats.vpp_raw);
                      snap.freq_hz = (float)stats.freq_zc;
                      snap.nsamples = stats.nsamples;

                      ret = wave_store_save(&store, &snap);
                      if (ret == 0)
                        {
                          store.seq++;
                        }

                      printf("[input] long press: snapshot #%u\n",
                             snap.seq);

                      /* Blink all LEDs to confirm the snapshot. */

                      if (led_fd >= 0)
                        {
                          ioctl(led_fd, ULEDIOC_SETALL, 0x7);
                          usleep(200000);
                          ioctl(led_fd, ULEDIOC_SETALL, 0x0);
                        }
                    }
                }
            }

          /* M6: threshold alarm -- light LED0 when Vpp is too high. */

          if (led_fd >= 0)
            {
              bool alarm = (wave_core_raw_to_volt(stats.vpp_raw) * 1000.0) >
                           CONFIG_OPENWAVE_ALARM_VPP_MV;

              ioctl(led_fd, ULEDIOC_SETALL,
                    (unsigned long)(alarm ? 0x1 : 0x0));
            }

          if (!infinite && --remaining == 0)
            {
              break;
            }
        }
    }
  else
    {
      /* M2/M3 raw-sample printing mode. */

      while (infinite || remaining > 0)
        {
          n = wave_core_read(&core, samples, WAVE_ADC_BATCH);
          if (n < 0)
            {
              printf("ADC read failed: %d\n", -n);
              break;
            }

          for (i = 0; i < n; i++)
            {
              printf("ch %u: raw %" PRId32 "  %" PRIu32 " mV\n",
                     samples[i].ch, samples[i].raw,
                     wave_core_to_mv(samples[i].raw));

              if (!infinite && --remaining == 0)
                {
                  break;
                }
            }

          fflush(stdout);
        }
    }

  if (led_fd >= 0)
    {
      ioctl(led_fd, ULEDIOC_SETALL, 0x0);
      close(led_fd);
    }

  if (rtc_fd >= 0)
    {
      close(rtc_fd);
    }

  wave_input_deinit(&input);
  wave_store_deinit(&store);
  wave_core_deinit(&core);
  if (ui_on)
    {
      wave_ui_deinit(&ui);
    }

  if (pwm_on)
    {
      wave_gen_deinit(&gen);
    }

  printf("OpenWave stopped.\n");
  return 0;
}

content.text:
The mtd_progmem.c ioctl handler supports:
- MTDIOC_GEOMETRY ✓
- MTDIOC_BULKERASE (erase entire device!)
- MTDIOC_ERASESTATE
- and apparently something at line 342 with "numsectors" (maybe MTDIOC_ERASESTATE or another command)

**NO MTDIOC_ERASESECTORS!** That's why ENOTTY. So the progmem driver doesn't support partial erase via ERASESECTORS. Only BULKERASE (whole device) or the underlying MTD's erase is used internally.

Hmm — wait, the char device wrapper: `register_mtddriver` — maybe the ioctl goes through the char wrapper which translates... no, the error came from the driver chain.

So options:
1. **Use MTDIOC_BULKERASE** — erases the WHOLE flash including the firmware!! ABSOLUTELY NOT — it would brick the board (need openocd re-flash). NOT acceptable.

2. **Erase the specific block via the raw progmem ops** — not accessible from userspace.

3. **Write without erasing** — flash programming requires erased (0xFF) cells to write 0 bits. If the last sector was never written (still 0xFF), a first write works without erase! But subsequent writes to the same sector would fail (can't clear already-written bits... actually writing 0s over 1s works; writing 1s over 0s doesn't). For a snapshot overwrite pattern, repeated saves to the SAME offset would eventually fail (bits already 0 can't be set back to 1).

Hmm — actually, wait: does the MTD's write function check erase state? up_progmem_write may verify... it might just write. If the sector is all 0xFF (factory fresh), the first save works. The verify (read-back) would pass. The SECOND save to the same offset would write a DIFFERENT snapshot (different seq, different time) — writing 1s where 0s were → those bits stay 0 → verify fails (CRC mismatch). So the second save would fail.

4. **Write to a DIFFERENT offset each time** (append pattern): each snapshot at a new offset within the last sector; once the sector fills, can't erase → stops. For a demo (a few snapshots), the last sector (128KB) could hold ~2000 snapshots of 64 bytes... but each byte can only be written once (0→1 not allowed). Writes at different offsets are fine as long as each offset is only written once. So: append snapshots at increasing offsets within the last sector, up to a few thousand. On reboot, the seq would reset to 0 and the next save would target offset 0 again (already written) → fail.

Hmm — actually, for robustness, we could:
- Save at offset = last_offset + (seq % N) * sizeof(snapshot) where N = erasesize/sizeof(snapshot) (2048 slots). seq persists? Not persisted. On each run, seq starts at 0 → same slot → fails on second run.

5. **Erase the sector via the board's stm32 flash... not from userspace.**

6. Check if the char driver (mtd_rw) supports MTDIOC_ERASESECTORS and the error is elsewhere... The error is -ENOTTY which means "ioctl not supported". The chain: app ioctl → char driver ioctl → mtd->ioctl (progmem_ioctl). progmem_ioctl doesn't handle ERASESECTORS → returns -ENOTTY. So no partial erase available.

Hmm — wait, let me reconsider. The task book says: "若 MTD 实现复杂，第一版可先改为串口打印并预留接口" — the fallback is acceptable. But we can do better: implement a **write-once snapshot log** (append pattern) that works WITHOUT erase for the first N snapshots in a fresh sector, PLUS the console print. And for repeated runs, detect the failure and report it gracefully (console-only).

Actually — even better: we can erase the sector ONLY when needed by... no, no partial erase available.

Alternative: use MTDIOC_BULKERASE on a PARTITION? The OTA partition stuff: CONFIG_STM32_PROGMEM_OTA_PARTITION — if enabled, the board creates partitions (primary/secondary/scratch) as separate MTD devices registered at different paths (e.g., /dev/primary...). Those partitions would still map to the same flash (no separate erase granularity).

Hmm — what about the "scratch" partition concept: OTA systems erase the scratch sector. If we could register/use a partition covering ONLY the last sector, MTDIOC_BULKERASE on that partition would erase only the last sector! But the board config doesn't have OTA partitions enabled (CONFIG_STM32_PROGMEM_OTA_PARTITION — from the .config? Probably not set). And creating partitions requires the MTD partition framework + kernel-side setup. Too much.

Pragmatic solution for M6 v1 (per the task book's explicit allowance):
- Change wave_store_save to a **write-once log**: 
  - Find the first free slot in the last sector by scanning (read each slot; if magic==0xFF (erased) → free). 
  - Write the snapshot there.
  - If no free slot (sector full or previously written), report "flash full" and stay console-only.
- No erase needed (erase unsupported). On a fresh board (sector erased = 0xFF), the first ~2000 snapshots work. If the sector ever gets written by us, we can't re-erase from userspace — acceptable limitation; document it. Actually — we could ALSO try MTDIOC_BULKERASE as a LAST resort... NO — that erases the firmware. Never.

Wait — actually, hmm, let me reconsider: can we verify that writes even work? up_progmem_write on STM32H7 — writing to flash while executing from flash: the STM32H7 flash controller supports writing to a different bank while executing from the other bank (RWW — read-while-write). The firmware runs from bank 0 (0x08000000-0x08084xxx); the last sector is in bank 1 (0x081E0000). So writing bank 1 while executing bank 0 should work (H7 supports RWW across banks). ✓ Good.

But — does up_progmem_write require the flash to be UNLOCKED (flash_erase/write operations need the flash controller unlock sequence)? The nuttx stm32 progmem driver's up_progmem_write should handle locking internally. ✓ (it's used by the OTA/bootloader flows).

Also — the write might REQUIRE the target to be erased first (flash can only program 0s into erased 1s). The verify step would catch failures. For a fresh sector, the first writes work.

So the plan:
1. Modify wave_store_save: no erase. Scan the last sector for the first slot whose magic != 0xFFFFFFFF (erased state). If found, write there; if none, print "flash log full" and return -ENOSPC (console still prints).
   - Scanning: read sizeof(snapshot) at each slot offset; if the first 4 bytes == 0xFFFFFFFF → free.
   - Actually — the erased flash reads as 0xFF. A written slot has magic 0x4f57534e. So scan for magic==0xFFFFFFFF.
   - Number of slots = erasesize / sizeof(snapshot) = 131072/64 = 2048.
   - Read cost: 2048 × 64B reads — fine.

2. Keep the console print (always).

3. Remove the erase ioctl (it's unsupported).

Also fix: `snap.seq` — after a successful flash write, seq++. On restart, seq resets to 0 but the slot scan finds the next free slot — the printed seq would repeat (0,1,2...) across reboots, but the stored snapshots are all in different slots ✓. Good enough.

Also — the `[store]` success message should say which slot/offset.

Let me rewrite wave_store.c's save function accordingly. Since editing the VM file via patches is error-prone, I'll regenerate the whole wave_store.c and re-ship via base64 (it's small, 3988 bytes → ~5.3KB base64). Actually — simpler: give a targeted python patch for the save function? The changes are substantial (remove erase, add slot scan). A full-file replacement via base64 is cleaner.

Let me rewrite wave_store.c locally:

```c
int wave_store_save(...)
{
  ...
  /* Console record */
  printf("[snapshot] ...");

  if (!st->opened || !st->geo_ok) { console-only; return -ENODEV; }

  /* Find the first free slot in the last erase block. */
  slot_size = sizeof(struct wave_snapshot_s);
  nslots = st->erasesize / slot_size;
  for (slot = 0; slot < nslots; slot++)
    {
      offset = st->last_offset + (off_t)slot * slot_size;
      nbytes = pread(st->fd, &probe, sizeof(probe), offset);
      if (nbytes == sizeof(probe) && probe.magic == 0xffffffffu)
        {
          free_slot = slot;
          break;
        }
    }
  if (free_slot < 0)
    {
      printf("[store] flash log full (console-only)\n");
      return -ENOSPC;
    }
  offset = st->last_offset + (off_t)free_slot * slot_size;

  /* Fill magic + crc */
  out = *snap; out.magic = MAGIC; out.crc = 0; out.crc = crc(&out);

  nbytes = pwrite(st->fd, &out, sizeof(out), offset);
  if (nbytes != sizeof) { print fail; return -EIO; }

  /* verify */
  memset(&check, 0, sizeof(check));
  nbytes = pread(st->fd, &check, sizeof(check), offset);
  if (verify magic + crc) { printf OK at offset; return 0; }
  print verify failed; return -EIO;
}
```

Wait — one concern: reading flash via pread at offsets — the MTD char driver's read → progmem_read → up_progmem_read. Does up_progmem_read work for reading flash? It should (flash is readable). CONFIG_ARCH_HAVE_PROGMEM_READ needed for the read path — from the earlier grep: `#ifdef CONFIG_ARCH_HAVE_PROGMEM_READ ... result = up_progmem_read(...)`. If that config isn't set, progmem_read might return... let me check what progmem_read does without CONFIG_ARCH_HAVE_PROGMEM_READ. From the grep earlier:
```
249: off_t startblock = offset >> priv->blkshift;
250: #ifdef CONFIG_ARCH_HAVE_PROGMEM_READ
253: result = up_progmem_read(...)
...
265: (offset & ...);  // else branch?
```
Line 265 was in the read function — probably `memcpy` from the flash address (direct read). So read works regardless (either via up_progmem_read or direct memcpy). ✓

And the earlier GEOMETRY + write test — the write hasn't been tested yet (erase failed first). We'll test after this fix.

Also — the `0xffffffffu` magic check: the erased state. Note the check struct probe has magic field — if erased, magic reads 0xFFFFFFFF ✓.

Let me also double-check the scan loop reading beyond... nslots = 131072/64 = 2048 slots, reading each — that's 2048 pread calls × 64B. Fine.

Let me regenerate wave_store.c with this change, base64 it, and deliver. Also update the local workspace file.

Also — the `[store] erase failed` bug is gone; new messages: `[store] OK: slot %u at offset 0x%lx` etc.

Let me update the local wave_store.c via apply_patch (replace the save function), then base64 just wave_store.c.

Actually — the save function changes: remove erase struct/ioctl, add slot scan. Let me apply_patch the local file.

